// Top-K (K = 2048) indexer token selection for decode: the K largest FP32 scores
// of every row in [B, S], returned as values plus int64 column indices.
//
// Radix selection on the order-preserving uint32 view of the float. Every score
// byte of the 32-bit key is resolved without sorting:
//
//   scores --[hist]--> per-row histogram of the top 11 key bits
//              |
//              +--[gather]--> largest 11-bit digit D that still leaves room:
//              |              digit > D  => selected (written straight out)
//              |              digit == D => candidate (compacted, key + index)
//              |
//              +--[finalize]--> two more radix levels over the candidates only,
//                               which resolve the exact K-th key.
//
//   key = bits "'^ (bits >> 31 ? ~0 : 0x80000000)   // -inf .. +inf ascending
//
// Bin counts are histogrammed in shared memory per block and folded into one
// global histogram per row with a single atomic round. The cut bin is derived
// from the suffix sums of that histogram, computed redundantly by every block.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <mutex>
#include <string>
#include <unordered_map>

namespace {

// Row passes: every thread walks kWindow scores per grid step.
constexpr int kThreads = 256;
constexpr int kWarps = kThreads / 32;
constexpr int kWindow = 4;
constexpr int kMaxBlocks = 512;

// Radix digits, most significant first. 11 + 11 + 10 covers the 32-bit key.
constexpr int kLevel1Bits = 11;
constexpr int kLevel2Bits = 11;
constexpr int kLevel3Bits = 10;
constexpr int kLevel1Bins = 1 << kLevel1Bits;
constexpr int kLevel2Bins = 1 << kLevel2Bits;
constexpr int kLevel3Bins = 1 << kLevel3Bits;

constexpr int kLevel2Shift = 32 - kLevel1Bits - kLevel2Bits;
constexpr uint32_t kLevel1Unit = 1u << (32 - kLevel1Bits);  // one level-1 digit
constexpr uint32_t kLevel2Mask = (uint32_t)kLevel2Bins - 1u;
constexpr uint32_t kLevel3Mask = (uint32_t)kLevel3Bins - 1u;
constexpr uint32_t kNoBin = 0xFFFFFFFFu;

// Floats ordered by their bit pattern: flip the sign, invert negative patterns.
__device__ __forceinline__ uint32_t order_key(float value) {
  const uint32_t bits = __float_as_uint(value);
  return (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
}

// Exclusive prefix sum across the block; returns the sum held by the lanes
// below the caller. `scratch` holds one word per warp.
__device__ __forceinline__ uint32_t block_excl_scan(uint32_t* scratch,
                                                    uint32_t value) {
  const int lane = threadIdx.x & 31;
  const int warp = threadIdx.x >> 5;
  uint32_t inclusive = value;
#pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
    const uint32_t other = __shfl_up_sync(0xffffffffu, inclusive, offset);
    if (lane >= offset) inclusive += other;
  }
  if (lane == 31) scratch[warp] = inclusive;
  __syncthreads();
  if (warp == 0) {
    uint32_t warp_sum = (lane < kWarps) ? scratch[lane] : 0u;
#pragma unroll
    for (int offset = 1; offset < kWarps; offset <<= 1) {
      const uint32_t other = __shfl_up_sync(0xffffffffu, warp_sum, offset);
      if (lane >= offset) warp_sum += other;
    }
    if (lane < kWarps) scratch[lane] = warp_sum;
  }
  __syncthreads();
  const uint32_t above = (warp == 0) ? 0u : scratch[warp - 1];
  return above + inclusive - value;
}

// suf[bin] = number of keys strictly above `bin`. Thread t owns the segment of
// kPer consecutive bins starting at the top of the digit range, so the segment
// sums are already ordered from the most significant digit down. *cut is set to
// the smallest bin whose suffix count is below `limit`: the bin that owns the
// limit-th largest key.
template <int BINS>
__device__ __forceinline__ void suffix_cut(const uint32_t* counts, uint32_t* suf,
                                           uint32_t* scratch, uint32_t* cut,
                                           uint32_t limit) {
  constexpr int kPer = BINS / kThreads;
  const int t = threadIdx.x;
  uint32_t own[kPer];
  uint32_t total = 0;
#pragma unroll
  for (int j = 0; j < kPer; ++j) {
    own[j] = counts[BINS - 1 - (t * kPer + j)];
    total += own[j];
  }
  uint32_t running = block_excl_scan(scratch, total);
  int best = BINS;
#pragma unroll
  for (int j = 0; j < kPer; ++j) {
    const int bin = BINS - 1 - (t * kPer + j);
    suf[bin] = running;
    if (running < limit) best = bin;
    running += own[j];
  }
  if (best < BINS) atomicMin(cut, (uint32_t)best);
  __syncthreads();
}

// Pass 1: per-row histogram of the top key digit.
__global__ void __launch_bounds__(kThreads) hist_kernel(
    const float* __restrict__ scores, int S, uint32_t* __restrict__ hist) {
  __shared__ uint32_t s_hist[kLevel1Bins];
  for (int bin = threadIdx.x; bin < kLevel1Bins; bin += kThreads) {
    s_hist[bin] = 0;
  }
  __syncthreads();

  const float* row = scores + (size_t)blockIdx.y * S;
  for (int i = blockIdx.x * kThreads + threadIdx.x; i < S;
       i += gridDim.x * kThreads) {
    atomicAdd(&s_hist[order_key(row[i]) >> (32 - kLevel1Bits)], 1u);
  }
  __syncthreads();

  uint32_t* out = hist + (size_t)blockIdx.y * kLevel1Bins;
  for (int bin = threadIdx.x; bin < kLevel1Bins; bin += kThreads) {
    const uint32_t count = s_hist[bin];
    if (count) atomicAdd(&out[bin], count);
  }
}

// Pass 2: resolve the cut digit, then split the row into selected scores and
// candidates in one sweep.
__global__ void __launch_bounds__(kThreads) gather_kernel(
    const float* __restrict__ scores, int S, int K,
    const uint32_t* __restrict__ hist, uint32_t* __restrict__ cut,
    uint32_t* __restrict__ counters, uint32_t* __restrict__ cand_key,
    uint32_t* __restrict__ cand_index, float* __restrict__ out_values,
    int64_t* __restrict__ out_indices) {
  __shared__ uint32_t s_suf[kLevel1Bins];
  __shared__ uint32_t s_scan[kWarps];
  __shared__ uint32_t s_cut;

  const int row = blockIdx.y;
  if (threadIdx.x == 0) s_cut = kNoBin;
  __syncthreads();
  suffix_cut<kLevel1Bins>(hist + (size_t)row * kLevel1Bins, s_suf, s_scan, &s_cut,
                          (uint32_t)K);

  // The cut digit and the number of scores above it are identical in every
  // block; block 0 publishes them for the finalize pass.
  const uint32_t cut_bin = s_cut;
  if (blockIdx.x == 0 && threadIdx.x == 0) {
    cut[row * 2] = cut_bin;
    cut[row * 2 + 1] = s_suf[cut_bin];
  }

  const uint32_t* row_scores = reinterpret_cast<const uint32_t*>(scores + (size_t)row * S);
  const uint32_t floor_key = cut_bin * kLevel1Unit;
  uint32_t* row_keys = cand_key + (size_t)row * S;
  uint32_t* row_index = cand_index + (size_t)row * S;
  float* row_values = out_values + (size_t)row * K;
  int64_t* row_out_index = out_indices + (size_t)row * K;

  for (int i = blockIdx.x * kThreads + threadIdx.x; i < S;
       i += gridDim.x * kThreads) {
    const uint32_t bits = __ldg(row_scores + i);
    const uint32_t key = bits ''^ (uint32_t)((int32_t)bits >> 31) | 0x80000000u;
    if (key < floor_key) continue;

    if (key >= floor_key + kLevel1Unit) {
      const uint32_t slot = atomicAdd(counters + row * 2, 1u);
      row_values[slot] = __uint_as_float(bits);
      row_out_index[slot] = (int64_t)i;
    } else {
      const uint32_t slot = atomicAdd(counters + row * 2 + 1, 1u);
      row_keys[slot] = key;
      row_index[slot] = (uint32_t)i;
    }
  }
}
