  float* row_values = out_values + (size_t)row * K;
  int64_t* row_out_index = out_indices + (size_t)row * K;

  for (int i = blockIdx.x * kThreads + threadIdx.x; i < S;
       i += gridDim.x * kThreads) {
    const float value = __ldg(row_in + i);
    const uint32_t key = order_key(value);
    if (key < floor_key) continue;

    if (key >= ceil_key) {
      const uint32_t slot = atomicAdd(counters + row * 2, 1u);
      row_values[slot] = value;
      row_out_index[slot] = (int64_t)i;
    } else {
      const uint32_t slot = atomicAdd(counters + row * 2 + 1, 1u);
      row_keys[slot] = key;
      row_index[slot] = (uint32_t)i;
    }
  }
}

// Pass 3: one block per row. Two extra radix levels over the candidates pin down
// the K-th key; the tail slots are then filled with the candidates on the edge.
// The same block clears the row scratch afterwards, so the next call starts from
// empty histogram and counters.
__global__ void __launch_bounds__(kThreads) finalize_kernel(
    const float* __restrict__ scores, int S, int K,
    const uint32_t* __restrict__ cut, uint32_t* __restrict__ counters,
    uint32_t* __restrict__ hist, const uint32_t* __restrict__ cand_key,
    const uint32_t* __restrict__ cand_index, float* __restrict__ out_values,
    int64_t* __restrict__ out_indices) {
  __shared__ uint32_t s_bins2[kLevel2Bins];
  __shared__ uint32_t s_suf2[kLevel2Bins];
  __shared__ uint32_t s_bins3[kLevel3Bins];
  __shared__ uint32_t s_suf3[kLevel3Bins];
  __shared__ uint32_t s_scan[kWarps];
  __shared__ uint32_t s_cut;
  __shared__ uint32_t s_taken;
  __shared__ uint32_t s_edge;

  const int row = blockIdx.y;
  const int t = threadIdx.x;
  const uint32_t cut_bin = cut[row * 2];
  const uint32_t selected = cut[row * 2 + 1];
  const int n_cand = (int)counters[row * 2 + 1];
  const uint32_t need = (uint32_t)K - selected;

  const uint32_t* row_keys = cand_key + (size_t)row * S;
  const uint32_t* row_index = cand_index + (size_t)row * S;

  // Level 2: which of the cut-bin candidates survive the remaining picks?
  for (int bin = t; bin < kLevel2Bins; bin += kThreads) s_bins2[bin] = 0;
  if (t == 0) s_cut = kNoBin;
  __syncthreads();
  for (int j = t; j < n_cand; j += kThreads) {
    atomicAdd(&s_bins2[(row_keys[j] >> kLevel2Shift) & kLevel2Mask], 1u);
  }
  __syncthreads();
  suffix_cut<kLevel2Bins>(s_bins2, s_suf2, s_scan, &s_cut, need);
  const uint32_t cut2 = s_cut;
  const uint32_t above2 = s_suf2[cut2];
  const uint32_t need3 = need - above2;  // picks left inside the level-2 bin

  // Level 3: only the candidates still tied on the level-2 digit matter. When
  // level 2 already exhausted the picks the mask keeps every tie out of range.
  uint32_t cut3 = (uint32_t)kLevel3Bins;
  uint32_t above3 = 0;
  if (need3 > 0) {
    for (int bin = t; bin < kLevel3Bins; bin += kThreads) s_bins3[bin] = 0;
    if (t == 0) s_cut = kNoBin;
    __syncthreads();
    for (int j = t; j < n_cand; j += kThreads) {
      const uint32_t key = row_keys[j];
      if (((key >> kLevel2Shift) & kLevel2Mask) != cut2) continue;
      atomicAdd(&s_bins3[key & kLevel3Mask], 1u);
    }
    __syncthreads();
    suffix_cut<kLevel3Bins>(s_bins3, s_suf3, s_scan, &s_cut, need3);
    cut3 = s_cut;
    above3 = s_suf3[cut3];
  }
  const uint32_t edge = need3 - above3;  // candidates equal to the K-th key

  if (t == 0) {
    s_taken = 0;
    s_edge = 0;
  }
  __syncthreads();

  const uint32_t threshold =
      (cut_bin << (kLevel2Bits + kLevel3Bits)) | (cut2 << kLevel3Bits) | cut3;
  const float* row_in = scores + (size_t)row * S;
  float* row_values = out_values + (size_t)row * K;
  int64_t* row_out_index = out_indices + (size_t)row * K;
  for (int j = t; j < n_cand; j += kThreads) {
    const uint32_t key = row_keys[j];
    if (key < threshold) continue;

    const uint32_t index = row_index[j];
    if (key > threshold) {
      const uint32_t slot = selected + atomicAdd(&s_taken, 1u);
      row_values[slot] = row_in[index];
      row_out_index[slot] = (int64_t)index;
    } else {
      const uint32_t slot = atomicAdd(&s_edge, 1u);
      if (slot < edge) {
        row_values[(uint32_t)K - edge + slot] = row_in[index];
        row_out_index[(uint32_t)K - edge + slot] = (int64_t)index;
      }
    }
  }

  // Reset for the next call: the row histogram and both candidate counters.
  uint32_t* row_hist = hist + (size_t)row * kLevel1Bins;
  for (int bin = t; bin < kLevel1Bins; bin += kThreads) row_hist[bin] = 0;
  if (t == 0) {
    counters[row * 2] = 0;
    counters[row * 2 + 1] = 0;
  }
}

struct Scratch {
  torch::Tensor hist;
  torch::Tensor counters;
  torch::Tensor cut;
  torch::Tensor cand_key;
  torch::Tensor cand_index;
};

// Per-(device, shape) device scratch, zeroed on creation and recycled by the
// finalize pass. Host-side state only; the device work stays in the kernels.
Scratch& scratch_for(const torch::Device& device, int64_t rows, int64_t columns) {
  static std::mutex mutex;
  static std::unordered_map<std::string, Scratch> cache;
  const std::string key =
      std::to_string(device.index()) + ":" + std::to_string(rows) + "x" +
      std::to_string(columns);

  std::lock_guard<std::mutex> lock(mutex);
  auto found = cache.find(key);
  if (found != cache.end()) return found->second;

  auto options = torch::TensorOptions().device(device);
  Scratch& entry = cache[key];
  entry.hist = torch::zeros({rows * kLevel1Bins}, options.dtype(torch::kInt32));
  entry.counters = torch::zeros({rows * 2}, options.dtype(torch::kInt32));
  entry.cut = torch::zeros({rows * 2}, options.dtype(torch::kInt32));
  entry.cand_key = torch::empty({rows * columns}, options.dtype(torch::kInt32));
  entry.cand_index = torch::empty({rows * columns}, options.dtype(torch::kInt32));
  return entry;
}

void require_contract(const torch::Tensor& tensor, torch::ScalarType dtype,
                      const char* label) {
  TORCH_CHECK_VALUE(tensor.is_cuda(), label, " must be a CUDA tensor");
  TORCH_CHECK_TYPE(tensor.scalar_type() == dtype, label, " has the wrong dtype");
  TORCH_CHECK_VALUE(tensor.is_contiguous(), label, " must be contiguous");
}

void kernel(const torch::Tensor& values, const torch::Tensor& top_values,
            const torch::Tensor& indices) {
  require_contract(values, torch::kFloat32, "values");
  require_contract(top_values, torch::kFloat32, "top_values");
  require_contract(indices, torch::kInt64, "indices");
  TORCH_CHECK_VALUE(values.dim() == 2, "values must be [batch, tokens]");
  TORCH_CHECK_VALUE(top_values.dim() == 2 && indices.dim() == 2,
                    "outputs must be [batch, k]");

  const int64_t rows = values.size(0);
  const int64_t columns = values.size(1);
  const int64_t k = top_values.size(1);
  TORCH_CHECK_VALUE(k >= 1 && k <= columns, "k must be in [1, tokens]");
  TORCH_CHECK_VALUE(top_values.size(0) == rows && indices.size(0) == rows &&
                        indices.size(1) == k,
                    "output shape mismatch");
  TORCH_CHECK_VALUE(values.device() == top_values.device() &&
                        values.device() == indices.device(),
                    "device mismatch");
  if (rows == 0) return;

  c10::cuda::CUDAGuard guard(values.device());
  const cudaStream_t stream =
      c10::cuda::getCurrentCUDAStream(values.get_device()).stream();
  const int S = (int)columns;
  const int K = (int)k;
  const Scratch& scratch = scratch_for(values.device(), rows, columns);
  const auto cuda_dtype = torch::TensorOptions().dtype(torch::kInt32);
  uint32_t* hist = reinterpret_cast<uint32_t*>(scratch.hist.data_ptr<int32_t>());
  uint32_t* counters =
      reinterpret_cast<uint32_t*>(scratch.counters.data_ptr<int32_t>());
  uint32_t* cut = reinterpret_cast<uint32_t*>(scratch.cut.data_ptr<int32_t>());
  uint32_t* cand_key =
      reinterpret_cast<uint32_t*>(scratch.cand_key.data_ptr<int32_t>());
  uint32_t* cand_index =
      reinterpret_cast<uint32_t*>(scratch.cand_index.data_ptr<int32_t>());

  const int steps = (S + kThreads * kWindow - 1) / (kThreads * kWindow);
  const dim3 row_grid(std::min(steps, kMaxBlocks), (unsigned)rows);

  hist_kernel<<<row_grid, kThreads, 0, stream>>>(values.data_ptr<float>(), S,
                                                 hist);
  gather_kernel<<<row_grid, kThreads, 0, stream>>>(
      values.data_ptr<float>(), S, K, hist, cut, counters, cand_key, cand_index,
      top_values.data_ptr<float>(), indices.data_ptr<int64_t>());
  const dim3 last_grid(1, (unsigned)rows);
  finalize_kernel<<<last_grid, kThreads, 0, stream>>>(
      values.data_ptr<float>(), S, K, cut, counters, hist, cand_key, cand_index,
      top_values.data_ptr<float>(), indices.data_ptr<int64_t>());
  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, "topk launch failed: ",
              cudaGetErrorString(error));
}
}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}
